inline ScopedFile scopedFile(IFileSystem* fs, File* file)
{
    return ScopedFile(file, v1::v1_detail::FileReleaser{ fs });
}
inline omni::expected<void, ErrorCode> setWorkingDirectory(IFileSystem* fs, cpp::zstring_view path)
{
    ScopedError holder;
    if (fs->setCurrentDirectoryPath(path.c_str()))
        return {};
    return omni::unexpected(carb::detail::getError());
}
inline omni::expected<void, ErrorCode> setAppDirectoryPath(IFileSystem* fs, cpp::zstring_view path)
{
    ScopedError holder;
    fs->setAppDirectoryPath(path.c_str());
    if (auto err = ErrorApi::getError())
        return omni::unexpected(ErrorCode{ err });
    return {};
}
inline omni::expected<omni::string, ErrorCode> getWorkingDirectory(IFileSystem* fs)
{
    ScopedError holder;
    if (auto buf = fs->getCurrentDirectoryPath())
        return omni::string(buf);
    return omni::unexpected(carb::detail::getError());
}
inline bool exists(IFileSystem* fs, cpp::zstring_view path, ErrorCode* ec = nullptr)
{
    ScopedError holder;
    if (fs->exists(path.c_str()))
        return true;
    if (ec)
        *ec = carb::detail::getError();
    return false;
}
inline omni::expected<ScopedFile, ErrorCode> openFile(IFileSystem* fs, cpp::zstring_view path, OpenMode mode)
{
    ScopedError holder;
    File* file;
    switch (mode)
    {
        default:
            return omni::unexpected(ErrorCode::kInvalidArgument);
        case OpenMode::eRead:
            file = fs->openFileToRead(path.c_str());
            break;
        case OpenMode::eWrite:
            file = fs->openFileToWrite(path.c_str());
            break;
        case OpenMode::eAppend:
            file = fs->openFileToAppend(path.c_str());
            break;
        case OpenMode::eReadWrite:
            file = fs->openFileToReadWrite(path.c_str());
            break;
    }
    if (file)
        return scopedFile(fs, file);
    return omni::unexpected(carb::detail::getError());
}
inline omni::expected<size_t, ErrorCode> getFileSize(IFileSystem* fs, ScopedFile& file)
{
    ScopedError holder;
    auto size = fs->getFileSize(file.get());
    if (size || ErrorApi::getError() == kResultSuccess)
        return size;
    return omni::unexpected(carb::detail::getError());
}
