inline omni::expected<omni::string, ErrorCode> makeCanonicalPath(IFileSystem* fs,
                                                                 cpp::zstring_view path,
                                                                 bool mustExist = true)
{
    omni::string str(128, '\0');
    ScopedError holder;
    auto bytes = fs->makeCanonicalPathEx2(
        path.c_str(), nullptr, mustExist ? fCanonicalFlagCheckExists : 0, str.data(), str.size());
    if (!bytes)
        return omni::unexpected(carb::detail::getError());
    if (bytes > str.size())
    {
        str.resize(bytes);
        bytes = fs->makeCanonicalPathEx2(
            path.c_str(), nullptr, mustExist ? fCanonicalFlagCheckExists : 0, str.data(), str.size());
        CARB_ASSERT(bytes && str.size() >= bytes);
    }
    str.resize(bytes - 1);
    return str;
}
inline omni::expected<CreateType, ErrorCode> makeDirectories(IFileSystem* fs, cpp::zstring_view path)
{
    ScopedError holder;
    if (fs->makeDirectories(path.c_str()))
        return ErrorApi::getError() == kResultAlreadyExists ? CreateType::eAlreadyExisted : CreateType::eWasCreated;
    return omni::unexpected(carb::detail::getError());
}
inline omni::expected<void, ErrorCode> removeDirectory(IFileSystem* fs, cpp::zstring_view path)
{
    ScopedError holder;
    if (fs->removeDirectory(path.c_str()))
        return {};
    return omni::unexpected(carb::detail::getError());
}
inline omni::expected<omni::string, ErrorCode> makeTempDirectory(IFileSystem* fs)
{
    omni::string buffer(512, '\0');
    ScopedError holder;
    if (fs->makeTempDirectory(buffer.data(), buffer.size()))
    {
        buffer.resize(std::strlen(buffer.c_str()));
        return buffer;
    }
    return omni::unexpected(carb::detail::getError());
}
template <typename Pred>
omni::expected<void, ErrorCode> forEachDirectoryItem(IFileSystem* fs, cpp::zstring_view path, bool recurse, Pred&& pred)
{
    using Type = std::decay_t<Pred>;
    auto wrapper = [](const DirectoryItemInfo* const info, void* ud) {
        auto& pred = *static_cast<Type*>(ud);
        return pred(*static_cast<const FileInfo*>(info), cpp::zstring_view(cpp::unsafe_length, info->path));
    };
    ScopedError holder;
    if (recurse)
        fs->forEachDirectoryItemRecursive(path.c_str(), wrapper, &pred);
    else
        fs->forEachDirectoryItem(path.c_str(), wrapper, &pred);
    if (auto err = carb::detail::getError(); err != ErrorCode{})
        return omni::unexpected(err);
    return {};
}
